ography\":{\"fontSize\":\"50px\",\"fontStyle\":\"normal\",\"fontWeight\":\"700\"}},\"textColor\":\"primary\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading has-primary-color has-text-color has-bricolage-grotesque-font-family\" style=\"font-size:50px;font-style:normal;font-weight:700\">We Can Help Turn Your<br>Ideas Into Reality!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"typography\":{\"lineHeight\":\"1.8\"}},\"textColor\":\"primary\",\"fontSize\":\"medium\",\"fontFamily\":\"inter\"} -->\n<p class=\"has-text-align-left has-primary-color has-text-color has-inter-font-family has-medium-font-size\" style=\"line-height:1.8\">Lorem Ipsum has been the industrys standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"accent\",\"textColor\":\"background\",\"className\":\"theme-btn\",\"style\":{\"border\":{\"radius\":\"30px\"}},\"fontFamily\":\"bricolage-grotesque\"} -->\n<div class=\"wp-block-button theme-btn\"><a class=\"wp-block-button__link has-background-color has-accent-background-color has-text-color has-background has-bricolage-grotesque-font-family wp-element-button\" href=\"#\" style=\"border-radius:30px\"><strong>READ MORE</strong></a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"\"} -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"wow fadeInUp\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"100%\"}} -->\n<div class=\"wp-block-group wow fadeInUp\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"30%\",\"className\":\"phone-number-box\",\"style\":{\"color\":{\"background\":\"var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dcolor\\u002d\\u002dsecaccent)\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\",\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-column phone-number-box has-background\" style=\"background-color:var(--wp--preset--color--secaccent);padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--80);flex-basis:30%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div></main>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {\"height\":\"50px\"} -->\n<div style=\"height:50px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"services-box\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"80%\"}} -->\n<div class=\"wp-block-group services-box\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"wow fadeInUp\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"2px\"}},\"fontSize\":\"upper-heading\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading has-text-align-center wow fadeInUp has-bricolage-grotesque-font-family has-upper-heading-font-size\" style=\"font-style:normal;font-weight:400;letter-spacing:2px;text-transform:uppercase\">OUR SERVICES</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"className\":\"wow fadeInUp\",\"style\":{\"typography\":{\"fontSize\":\"40px\",\"fontStyle\":\"normal\",\"fontWeight\":\"600\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"var:preset|spacing|50\",\"bottom\":\"0\",\"left\":\"var:preset|spacing|50\"}}},\"fontFamily\":\"bricolage-grotesque\"} -->\n<h3 class=\"wp-block-heading has-text-align-center wow fadeInUp has-bricolage-grotesque-font-family\" style=\"padding-top:0;padding-right:var(--wp--preset--spacing--50);padding-bottom:0;padding-left:var(--wp--preset--spacing--50);font-size:40px;font-style:normal;font-weight:600\">Awesome Services To Grow Your<br>Business Value</h3>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"50px\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div style=\"margin-top:0;margin-bottom:0;height:50px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"wow fadeInUp\"} -->\n<div class=\"wp-block-columns alignwide wow fadeInUp\"><!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:group {\"className\":\"service-inner-box\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group service-inner-box\"><!-- wp:image {\"id\":112,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8888/tinfox/wp-content/uploads/2025/05/undraw_android_vygj.png\" alt=\"\" class=\"wp-image-112\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"services-inner-short\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"letterSpacing\":\"1px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|80\"}}},\"backgroundColor\":\"background\",\"textColor\":\"accent\",\"fontSize\":\"extra-small\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading services-inner-short has-accent-color has-background-background-color has-text-color has-background has-link-color has-bricolage-grotesque-font-family has-extra-small-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--30);font-style:normal;font-weight:500;letter-spacing:1px\">ANDROID APP DEVELOPMENT</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>We build high-quality Android applications using modern technologies like Kotlin and Jetpack Compose, ensuring optimal performance and user experience.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:group {\"className\":\"service-inner-box\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group service-inner-box\"><!-- wp:image {\"id\":121,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8888/tinfox/wp-content/uploads/2025/05/undraw_mobile-images_b202.png\" alt=\"\" class=\"wp-image-121\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"services-inner-short\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"letterSpacing\":\"1px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|80\"}}},\"backgroundColor\":\"background\",\"textColor\":\"accent\",\"fontSize\":\"extra-small\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading services-inner-short has-accent-color has-background-background-color has-text-color has-background has-link-color has-bricolage-grotesque-font-family has-extra-small-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--30);font-style:normal;font-weight:500;letter-spacing:1px\">iOS APP DEVELOPMENT</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>Our team creates elegant iOS applications with Swift and SwiftUI, following Apple\'s design guidelines for seamless integration with the Apple ecosystem.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:group {\"className\":\"service-inner-box\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group service-inner-box\"><!-- wp:image {\"id\":120,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8888/tinfox/wp-content/uploads/2025/05/undraw_web-development_0wdh.png\" alt=\"\" class=\"wp-image-120\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"services-inner-short\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"letterSpacing\":\"1px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|80\"}}},\"backgroundColor\":\"background\",\"textColor\":\"accent\",\"fontSize\":\"extra-small\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading services-inner-short has-accent-color has-background-background-color has-text-color has-background has-link-color has-bricolage-grotesque-font-family has-extra-small-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--30);font-style:normal;font-weight:500;letter-spacing:1px\">BACKEND DEVELOPMENT</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>We develop scalable backend systems with Node.js, Python, and Java, implementing secure APIs, databases, and cloud infrastructure.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"wow fadeInUp\"} -->\n<div class=\"wp-block-columns alignwide wow fadeInUp\"><!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:group {\"className\":\"service-inner-box\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group service-inner-box\"><!-- wp:image {\"id\":118,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8888/tinfox/wp-content/uploads/2025/05/undraw_progressive-app_9517.png\" alt=\"\" class=\"wp-image-118\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"services-inner-short\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"letterSpacing\":\"1px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|80\"}}},\"backgroundColor\":\"background\",\"textColor\":\"accent\",\"fontSize\":\"extra-small\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading services-inner-short has-accent-color has-background-background-color has-text-color has-background has-link-color has-bricolage-grotesque-font-family has-extra-small-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--30);font-style:normal;font-weight:500;letter-spacing:1px\">CROSS-PLATFORM DEVELOPMENT</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>For businesses needing both iOS and Android apps, we offer Flutter and React Native solutions that save time and reduce costs.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:group {\"className\":\"service-inner-box\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group service-inner-box\"><!-- wp:image {\"id\":114,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8888/tinfox/wp-content/uploads/2025/05/undraw_maintenance_rjtm.png\" alt=\"\" class=\"wp-image-114\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"services-inner-short\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"letterSpacing\":\"1px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|80\"}}},\"backgroundColor\":\"background\",\"textColor\":\"accent\",\"fontSize\":\"extra-small\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading services-inner-short has-accent-color has-background-background-color has-text-color has-background has-link-color has-bricolage-grotesque-font-family has-extra-small-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--30);font-style:normal;font-weight:500;letter-spacing:1px\">APP MAINTENANCE</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p>Our ongoing support services ensure your applications stay updated, secure, and compatible with the latest OS versions.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:group {\"className\":\"service-inner-box\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group service-inner-box\"><!-- wp:image {\"id\":119,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8888/tinfox/wp-content/uploads/2025/05/undraw_wordpress_l75e.png\" alt=\"\" class=\"wp-image-119\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"services-inner-short\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"letterSpacing\":\"1px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|accent\"}}},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|80\"}}},\"backgroundColor\":\"background\",\"textColor\":\"accent\",\"fontSize\":\"extra-small\",\"fontFamily\":\"bricolage-grotesque\"} -->\n<h2 class=\"wp-block-heading services-inner-short has-accent-color has-background-background-color has-text-color has-background has-link-color has-bricolage-grotesque-font-family has-extra-small-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--30);font-style:normal;font-weight:500;letter-spacing:1px\">WORDPRESS WEBSITE DEVELOPMENT</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>WordPress Development custom themes, plugins, and fast, secure websites. Boost your brand with scalable WordPress solutions.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"70px\"} -->\n<div style=\"height:70px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"app-development-company\",\"tagName\":\"footer\"} /-->', 'Front Page', 'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'inherit', 'closed', 'closed', '', '12-revision-v1', '', '', '2025-05-18 13:52:32', '2025-05-18 13:52:32', '', 12, 'http://localhost:8888/tinfox/?p=132', 0, 'revision', '', 0),
